const ROLE_TYPES = [
  { key: "Warrior", label: "Warrior", icon: ROLE_ICONS.Warrior },
  { key: "Mage", label: "Mage", icon: ROLE_ICONS.Mage },
  { key: "Archer", label: "Archer", icon: ROLE_ICONS.Archer },
  { key: "Martial Artist", label: "Martial Artist", icon: ROLE_ICONS["Martial Artist"] },
];

// Default set (Crusher and any raid without its own task list):
// same options for both Assignment SP and Assignment PSP, no levers.
const DEFAULT_TASKS = [
  "Start Mobs", "Start Mini", "Platform Mobs", "Platform Mini",
  "Phase 1", "Phase 2", "Phase 3",
];

// Per-raid tasks: psp = Assignment PSP, sp = Assignment SP, levers = Levers.
const RAID_TASKS = {
  "Nezarun v1": {
    psp: ["Mid", "100% boss", "50% boss", "25% boss"],
    sp: ["SP Debuff mid", "SP Debuff 100%", "SP Debuff 50%", "SP Debuff 25%"],
    levers: ["Lever 1+2", "Lever 3", "Portal"],
  },
  "Pollutus": {
    psp: ["Phase 1", "Phase 2", "Phase 3", "Mini"],
    sp: ["SP Debuff mini", "SP Debuff p1", "SP Debuff p2", "SP Debuff p3"],
    levers: ["Lever 1", "Lever 2", "Lever 3", "Lever 4", "Portal"],
  },
  "Uarma": {
    psp: ["Boss", "Room 1", "Room 2", "Room 3"],
    sp: [],
    levers: [],
  },
  "Arma v1": {
    psp: ["Start mini", "Mid", "Boss"],
    sp: ["SP Debuff Start mini", "SP Debuff mid", "SP Debuff Boss"],
    levers: ["Lever 1", "Lever 2", "Lever 3", "Portal"],
  },
  "Yertirand": {
    psp: ["Boss 100%", "Boss 50%", "Boss 25%"],
    sp: ["SP Debuff 100%", "SP Debuff 50%", "SP Debuff 25%"],
    levers: [],
  },
  "Paimon": {
    psp: ["Boss", "Mini"],
    sp: ["SP Debuff Boss", "SP Debuff Mini"],
    levers: ["Lever", "Portal"],
  },
};

function tasksFor(raidName) {
  return RAID_TASKS[raidName] || { psp: DEFAULT_TASKS, sp: DEFAULT_TASKS, levers: [] };
}

export function emptyPlayer(id) {
  return { id, name: "", cls: "Warrior", sp: "", element: "", psp: "", spTasks: [], pspTasks: [], levers: [] };
}

function SpPicker({ cls, value, onChange , dropUp }) {
  const [open, setOpen] = useState(false);
  const clsInfo = CLASSES[cls];
  const icons = SP_ICONS[cls] || {};
  const options = Array.from({ length: clsInfo.spCount }, (_, i) => String(i + 1));
  const currentIcon = value ? icons[value] : null;

  return (
    <div className="relative">
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        className="w-full flex items-center gap-1.5 bg-slate-800 border border-slate-700 rounded-md px-2 py-1 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
      >
        {currentIcon ? (
          <img src={currentIcon} alt={`SP ${value}`} className="w-6 h-6 rounded" />
        ) : (
          <span className="w-6 h-6 rounded bg-slate-700 flex items-center justify-center text-[10px] text-slate-400">
            {value || "—"}
          </span>
        )}
        <span className="text-slate-300">{value ? `SP ${value}` : "Select SP"}</span>
      </button>

      {open && (
        <>
          <div className="fixed inset-0 z-10" onClick={() => setOpen(false)} />
          <div className={
            "absolute z-30 bg-slate-800 border border-slate-700 rounded-lg p-2 grid grid-cols-4 gap-1.5 shadow-xl w-max max-w-[16rem] " +
            (dropUp ? "bottom-full mb-1" : "mt-1")
          }>
            {options.map((n) => {
              const icon = icons[n];
              return (
                <button
                  key={n}
                  type="button"
                  onClick={() => {
                    onChange(n);
                    setOpen(false);
                  }}
                  title={`SP ${n}`}
                  className={
                    "flex flex-col items-center gap-0.5 rounded-md p-1 border transition " +
                    (value === n
                      ? "border-indigo-500 bg-indigo-500/20"
                      : "border-transparent hover:border-slate-600 hover:bg-slate-700")
                  }
                >
                  {icon ? (
                    <img src={icon} alt={`SP ${n}`} className="w-9 h-9 rounded" />
                  ) : (
                    <span className="w-9 h-9 rounded bg-slate-700 flex items-center justify-center text-xs text-slate-300">
                      {n}
                    </span>
                  )}
                  <span className="text-[10px] text-slate-400">{n}</span>
                </button>
              );
            })}
          </div>
        </>
      )}
    </div>
  );
}

function PspPicker({ value, onChange , dropUp }) {
  const [open, setOpen] = useState(false);
  const current = PSP_TYPES.find((t) => t.key === value);

  return (
    <div className="relative">
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        title={value || "Select PSP"}
        className="w-full flex items-center gap-1 bg-slate-800 border border-slate-700 rounded-md px-2 py-1 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500 min-h-[30px]"
      >
        {current ? (
          <span className="flex items-center -space-x-1">
            {current.icons.map((icon, i) => (
              <img key={i} src={icon} alt={current.label} className="w-6 h-6 rounded" />
            ))}
          </span>
        ) : (
          <span className="text-slate-400">PSP</span>
        )}
      </button>

      {open && (
        <>
          <div className="fixed inset-0 z-10" onClick={() => setOpen(false)} />
          <div className={
            "absolute z-30 bg-slate-800 border border-slate-700 rounded-lg p-2 grid grid-cols-4 gap-1.5 shadow-xl w-max max-w-[18rem] " +
            (dropUp ? "bottom-full mb-1" : "mt-1")
          }>
            <button
              type="button"
              onClick={() => {
                onChange("");
                setOpen(false);
              }}
              title="No PSP"
              className={
                "flex flex-col items-center justify-center gap-0.5 rounded-md p-1 border transition " +
                (value === ""
                  ? "border-indigo-500 bg-indigo-500/20"
                  : "border-transparent hover:border-slate-600 hover:bg-slate-700")
              }
            >
              <span className="w-9 h-9 rounded bg-slate-700 flex items-center justify-center text-slate-400">—</span>
              <span className="text-[9px] text-slate-400 text-center leading-tight">None</span>
            </button>
            {PSP_TYPES.map((t) => {
              const active = value === t.key;
              return (
                <button
                  key={t.key}
                  type="button"
                  onClick={() => {
                    onChange(t.key);
                    setOpen(false);
                  }}
                  title={t.label}
                  className={
                    "flex flex-col items-center gap-0.5 rounded-md p-1 border transition " +
                    (active
                      ? "border-indigo-500 bg-indigo-500/20"
                      : "border-transparent hover:border-slate-600 hover:bg-slate-700")
                  }
                >
                  <span className="flex items-center -space-x-1">
                    {t.icons.map((icon, i) => (
                      <img key={i} src={icon} alt={t.label} className="w-9 h-9 rounded" />
                    ))}
                  </span>
                  <span className="text-[9px] text-slate-400 text-center leading-tight">{t.label}</span>
                </button>
              );
            })}
          </div>
        </>
      )}
    </div>
  );
}

