function TaskChips({ tasks, selected, onToggle }) {
  if (!tasks || tasks.length === 0) {
    return <span className="text-slate-600 text-xs">—</span>;
  }
  return (
    <div className="flex flex-wrap gap-1">
      {tasks.map((task) => {
        const active = selected.includes(task);
        return (
          <button
            key={task}
            type="button"
            onClick={() => onToggle(task)}
            className={
              "text-xs px-2 py-1 rounded-full border transition " +
              (active
                ? "bg-indigo-500/20 border-indigo-500 text-indigo-200"
                : "bg-slate-800 border-slate-700 text-slate-400 hover:border-slate-500")
            }
          >
            {task}
          </button>
        );
      })}
    </div>
  );
}

export default function RaidPlanner({ session, onBack, onUpdate }) {
  const raidName = session.raidName;
  const raid = RAID_CONFIG[raidName];
  const hasElements = !!raid.elements;

  const [players, setPlayers] = useState(() =>
    session.players && session.players.length
      ? session.players
      : Array.from({ length: raid.slots }, (_, i) => emptyPlayer(i))
  );

  useEffect(() => {
    onUpdate(players);
  }, [players]);

  function updatePlayer(id, patch) {
    setPlayers((prev) =>
      prev.map((p) => (p.id === id ? { ...p, ...patch } : p))
    );
  }

  function toggleTask(id, field, task) {
    setPlayers((prev) =>
      prev.map((p) => {
        if (p.id !== id) return p;
        const list = p[field] || [];
        const has = list.includes(task);
        return { ...p, [field]: has ? list.filter((t) => t !== task) : [...list, task] };
      })
    );
  }

  const taskSet = tasksFor(raidName);
  const hasLevers = taskSet.levers.length > 0;
  const pspSpanClass = hasElements
    ? (hasLevers ? "col-span-2" : "col-span-3")
    : (hasLevers ? "col-span-3" : "col-span-4");

  const filledCount = players.filter((p) => p.name.trim()).length;

  const grouped = useMemo(() => {
    if (!hasElements) return null;
    const map = {};
    for (const el of raid.elements) map[el] = [];
    const unassigned = [];
    for (const p of players) {
      if (!p.name.trim()) continue;
      if (p.element && map[p.element]) map[p.element].push(p);
      else unassigned.push(p);
    }
    return { map, unassigned };
  }, [players, hasElements, raid]);

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 p-4 md:p-8">
      <div className="max-w-5xl mx-auto space-y-6">
        <header className="flex flex-wrap items-center gap-3">
          <button
            type="button"
            onClick={onBack}
            className="text-sm bg-slate-800 border border-slate-700 rounded-lg px-3 py-2 hover:border-slate-500 transition"
          >
            ← Back
          </button>
          <div>
            <h1 className="text-2xl font-bold tracking-tight">{raidName}</h1>
            <p className="text-slate-400 text-sm">
              {session.time ? `Starts at ${session.time}` : "No time set"}
            </p>
          </div>
          <span className="text-sm text-slate-400 ml-auto">
            {filledCount}/{raid.slots} filled
            {hasElements && <span className="ml-2">· elements: {raid.elements.join(" / ")}</span>}
          </span>
        </header>

        <div className="bg-slate-900 border border-slate-800 rounded-xl">
          <div className="grid grid-cols-12 gap-2 px-4 py-2 text-xs uppercase tracking-wide text-slate-500 border-b border-slate-800 bg-slate-900/60">
            <div className="col-span-1">#</div>
            <div className="col-span-2">Name</div>
            <div className="col-span-1">Class</div>
            <div className="col-span-1">SP Card</div>
            <div className="col-span-2">Assignment SP</div>
            <div className="col-span-1">PSP</div>
            {hasElements && <div className="col-span-1">Element</div>}
            <div className={pspSpanClass}>Assignment PSP</div>
            {hasLevers && <div className="col-span-1">Levers</div>}
          </div>

          <div className="divide-y divide-slate-800">
            {players.map((p, idx) => {
              const dropUp = idx >= players.length - 2;
              return (
                <div key={p.id} className="grid grid-cols-12 gap-2 px-4 py-2 items-center">
                  <div className="col-span-1 text-slate-500 text-sm">{idx + 1}</div>

                  <div className="col-span-2">
                    <input
                      value={p.name}
                      onChange={(e) => updatePlayer(p.id, { name: e.target.value })}
                      placeholder="Name"
                      className="w-full bg-slate-800 border border-slate-700 rounded-md px-2 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
                    />
                  </div>

                  <div className="col-span-1">
                    <ClassPicker
                      value={p.cls}
                      onChange={(val) => updatePlayer(p.id, { cls: val, sp: "" })}
                      dropUp={dropUp}
                    />
                  </div>

                  <div className="col-span-1">
                    <SpPicker
                      cls={p.cls}
                      value={p.sp}
                      onChange={(val) => updatePlayer(p.id, { sp: val })}
                      dropUp={dropUp}
                    />
                  </div>

                  <div className="col-span-2">
                    <TaskChips
                      tasks={taskSet.sp}
                      selected={p.spTasks}
                      onToggle={(t) => toggleTask(p.id, "spTasks", t)}
                    />
                  </div>

                  <div className="col-span-1">
                    <PspPicker
                      value={p.psp}
                      onChange={(val) => updatePlayer(p.id, { psp: val })}
                      dropUp={dropUp}
                    />
                  </div>

                  {hasElements && (
                    <div className="col-span-1">
                      <select
                        value={p.element}
                        onChange={(e) => updatePlayer(p.id, { element: e.target.value })}
                        className="w-full bg-slate-800 border border-slate-700 rounded-md px-2 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
                      >
                        <option value="">—</option>
                        {raid.elements.map((el) => (
                          <option key={el} value={el}>{el}</option>
                        ))}
                      </select>
                    </div>
                  )}

                  <div className={pspSpanClass}>
                    <TaskChips
                      tasks={taskSet.psp}
                      selected={p.pspTasks}
                      onToggle={(t) => toggleTask(p.id, "pspTasks", t)}
                    />
                  </div>

                  {hasLevers && (
                    <div className="col-span-1">
                      <TaskChips
                        tasks={taskSet.levers}
                        selected={p.levers}
                        onToggle={(t) => toggleTask(p.id, "levers", t)}
                      />
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>

        <section className="space-y-3">
          <h2 className="text-sm uppercase tracking-wide text-slate-500">
            Discord preview — screenshot this part
          </h2>

          <div className="bg-slate-900 border border-slate-800 rounded-xl p-5">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-xl font-bold">📢 {raidName}</h3>
              <span className="text-base text-slate-400">{filledCount}/{raid.slots}</span>
            </div>

            {!hasElements && (
              <ol className="space-y-2">
                {players.filter((p) => p.name.trim()).map((p, i) => (
                  <PlayerLine key={p.id} index={i + 1} p={p} />
                ))}
                {filledCount === 0 && (
                  <p className="text-slate-500 text-sm">No players filled in yet.</p>
                )}
              </ol>
            )}

            {hasElements && grouped && (
              <div className="space-y-4">
                {raid.elements.map((el) => {
                  const style = ELEMENT_STYLE[el];
                  const list = grouped.map[el];
                  return (
                    <div key={el}>
                      <div className="flex items-center gap-2 mb-1.5">
                        <span className={"w-2 h-2 rounded-full " + style.bar} />
                        <span className={"text-base font-semibold " + style.text}>{el}</span>
                        <span className="text-sm text-slate-500">({list.length})</span>
                      </div>
                      {list.length === 0 ? (
                        <p className="text-slate-600 text-xs italic pl-4">empty</p>
                      ) : (
                        <ol className="space-y-1.5 pl-4">
                          {list.map((p, i) => (
                            <PlayerLine key={p.id} index={i + 1} p={p} />
                          ))}
                        </ol>
                      )}
                    </div>
                  );
                })}
                {grouped.unassigned.length > 0 && (
                  <div>
                    <span className="text-base font-semibold text-slate-400">No element</span>
                    <ol className="space-y-1.5 pl-4 mt-1.5">
                      {grouped.unassigned.map((p, i) => (
                        <PlayerLine key={p.id} index={i + 1} p={p} />
                      ))}
                    </ol>
                  </div>
                )}
              </div>
            )}
          </div>
        </section>
      </div>
    </div>
  );
}

// ---------------------------------------------------------------
// Short text line for copying into in-game chat, e.g.
//   john/SP6/DBF mini+50%/Pri p2/Lever 1+2+3/Portal
// ---------------------------------------------------------------
const PSP_SHORT = {
  Primary: "Pri",
  Secondary: "Sec",
  Element: "Ele",
  Dog: "Dog",
  "Lucy/Cheongbi": "Lucy/Chngb",
  "Ragnar/Neza": "Rag/Neza",
  Jinn: "Jinn",
};

function shortSpTask(task) {
  // "SP Debuff mini" -> "mini", "SP Debuff 50%" -> "50%"
  return task.replace(/^SP Debuff\s*/i, "");
}

function shortPspTask(task) {
  // "Phase 2" -> "p2", "100% boss" -> "100%", "Room 1" -> "R1"
  const phase = task.match(/^Phase\s*(\d+)$/i);
  if (phase) return "p" + phase[1];

  const room = task.match(/^Room\s*(\d+)$/i);
  if (room) return "R" + room[1];

  return task
    .replace(/\s*boss$/i, "")
    .replace(/^Boss\s+/i, "")
    .trim();
}

function shortLever(task) {
  // "Lever 1+2+3" -> "L1+2+3", "Lever" -> "L", "Portal" stays as is
  return task.replace(/^Lever\s*/i, "L");
}

function buildCopyText(p) {
  const parts = [];

  parts.push(p.name.trim() || "?");

  if (p.sp) parts.push("SP" + p.sp);

  if (p.spTasks && p.spTasks.length > 0) {
    parts.push("DBF " + p.spTasks.map(shortSpTask).join("+"));
  }

  const pspBits = [];
  if (p.psp) pspBits.push(PSP_SHORT[p.psp] || p.psp);
  if (p.pspTasks && p.pspTasks.length > 0) {
    pspBits.push(p.pspTasks.map(shortPspTask).join("+"));
  }
  if (pspBits.length) parts.push(pspBits.join(" "));

  if (p.levers && p.levers.length > 0) {
    for (const lever of p.levers) parts.push(shortLever(lever));
  }

  return parts.join("/");
}

async function copyToClipboard(text) {
  try {
    await navigator.clipboard.writeText(text);
    return true;
  } catch (e) {
    // Fallback for browsers/contexts without the async clipboard API.
    try {
      const el = document.createElement("textarea");
      el.value = text;
      el.style.position = "fixed";
      el.style.opacity = "0";
      document.body.appendChild(el);
      el.select();
      const ok = document.execCommand("copy");
      document.body.removeChild(el);
      return ok;
    } catch (e2) {
      return false;
    }
  }
}

function CopyButton({ player }) {
  const [copied, setCopied] = useState(false);

  async function handleCopy() {
    const ok = await copyToClipboard(buildCopyText(player));
    if (!ok) return;
    setCopied(true);
    setTimeout(() => setCopied(false), 1500);
  }

  return (
    <button
      type="button"
      onClick={handleCopy}
      title={buildCopyText(player)}
      className={
        "ml-auto shrink-0 text-[10px] px-2 py-0.5 rounded border transition " +
        (copied
          ? "border-emerald-500 text-emerald-300 bg-emerald-500/10"
          : "border-slate-700 text-slate-500 hover:text-slate-200 hover:border-slate-500")
      }
    >
      {copied ? "Copied" : "Copy"}
    </button>
  );
}

function PlayerLine({ index, p }) {
  const roleIcon = ROLE_ICONS[p.cls];
  const spIcon = p.sp ? (SP_ICONS[p.cls] || {})[p.sp] : null;
  const pspType = p.psp ? PSP_TYPES.find((x) => x.key === p.psp) : null;

  const hasSp = !!p.sp || (p.spTasks && p.spTasks.length > 0);
  const hasPsp = !!pspType || (p.pspTasks && p.pspTasks.length > 0);
  const hasLevers = p.levers && p.levers.length > 0;

  return (
    <li className="text-base flex flex-wrap items-center gap-x-4 gap-y-2">
      <span className="text-slate-500 w-6 shrink-0">{index}.</span>

      {roleIcon && (
        <img src={roleIcon} alt={p.cls} title={p.cls} className="w-7 h-7 rounded shrink-0" />
      )}

      <span className="font-semibold text-base">{p.name}</span>

      {hasSp && (
        <span className="flex items-center gap-1.5 rounded-md bg-sky-500/10 border border-sky-500/30 px-2 py-1">
          {spIcon ? (
            <img src={spIcon} alt={`SP ${p.sp}`} title={`SP ${p.sp}`} className="w-7 h-7 rounded" />
          ) : (
            p.sp && <span className="text-sky-200 text-sm">SP {p.sp}</span>
          )}
          {p.spTasks && p.spTasks.length > 0 && (
            <span className="text-sky-200 text-sm">{p.spTasks.join(" + ")}</span>
          )}
        </span>
      )}

      {hasPsp && (
        <span className="flex items-center gap-1.5 rounded-md bg-fuchsia-500/10 border border-fuchsia-500/30 px-2 py-1">
          {pspType && (
            <span className="flex items-center -space-x-1" title={pspType.label}>
              {pspType.icons.map((icon, i) => (
                <img key={i} src={icon} alt={pspType.label} className="w-7 h-7 rounded" />
              ))}
            </span>
          )}
          {p.pspTasks && p.pspTasks.length > 0 && (
            <span className="text-fuchsia-200 text-sm">{p.pspTasks.join(" + ")}</span>
          )}
        </span>
      )}

      {hasLevers && (
        <span className="rounded-md bg-amber-500/10 border border-amber-500/30 px-2 py-1 text-amber-200 text-sm">
          {p.levers.join(" + ")}
        </span>
      )}

      <CopyButton player={p} />
    </li>
  );
}
